/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones. Numbers that left the
 * project with a moved issue are kept in the high-water row and never reissued.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const retired = getDb()
    .select({ value: issueNumberHighWaters.highWater })
    .from(issueNumberHighWaters)
    .where(
      and(
        orgPredicate(issueNumberHighWaters.orgId, orgId),
        eq(issueNumberHighWaters.projectId, projectId),
      ),
    )
    .get();
  return Math.max(row?.value ?? 0, retired?.value ?? 0) + 1;
}

/** Records that `issueNumber` has been issued in `projectId`, never lowering it. */
function reserveIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): void {
  const db = getDb();
  const current = db
    .select({ value: issueNumberHighWaters.highWater })
    .from(issueNumberHighWaters)
    .where(eq(issueNumberHighWaters.projectId, projectId))
    .get();

  if (current === undefined) {
    db.insert(issueNumberHighWaters)
      .values({ orgId, projectId, highWater: issueNumber })
      .run();
  } else if (issueNumber > current.value) {
    db.update(issueNumberHighWaters)
      .set({ highWater: issueNumber })
      .where(eq(issueNumberHighWaters.projectId, projectId))
      .run();
  }
}

