/**
 * Moves an issue into `toProjectId`, giving it that project's next number. The
 * number it leaves behind is reserved in the source project so it is never
 * reissued there. Labels, comments and attachments stay attached by issue id.
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issue: Issue,
  toProjectId: ProjectId,
): Promise<Issue> {
  reserveIssueNumber(orgId, issue.projectId, issue.number);
  const number = await nextIssueNumber(orgId, toProjectId);

  const row = getDb()
    .update(issues)
    .set({
      projectId: toProjectId,
      number,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issue.id)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issue.id} not found`);

  const moved = await findIssueById(orgId, issue.id);
  if (!moved) throw new Error(`Issue ${issue.id} not found`);
  return moved;
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */

